import {esc,num,table,notes,sources,controlsHTML as baseControls,readControls,resultHTML as baseResult,bindResult as bindBase} from './bridges-views.js?v=20261030-construction1';
import {heatmapSVG} from './quantum-plots.js?v=20261030-construction1';
export {esc,num,table,notes,sources,readControls};
const ints=new Set(['copies','seedSite','period','qx','qy','points']);
export function controlsHTML(module,values){const keys={salc:['polarizationAngle','anisotropy'],wavevector:['phaseDegrees','relativePhaseDegrees','transverseRatio'],nonsymmorphic:['kFraction','mass','zeeman']}[module.id]||[];return baseControls({...module,fields:module.fields.map(f=>f.type==='number'&&!ints.has(f.key)?{...f,step:'any'}:f)},values)+`<details class="ct-sliders"><summary>拖动参数进行对照</summary><p>拖动同步更新输入；点击计算后更新结果。</p>${module.fields.filter(f=>keys.includes(f.key)).map(f=>`<label>${esc(f.label)}<input type="range" data-pr-control="${esc(f.key)}" min="${f.min??-5}" max="${f.max??5}" step="${f.step??.1}" value="${esc(values[f.key])}"></label>`).join('')}</details>`;}
const val=x=>typeof x==='number'?num(x):typeof x==='boolean'?(x?'是':'否'):x==null?'—':typeof x==='object'?JSON.stringify(x):String(x);
const opts=(rows,selected)=>rows.map(([id,label])=>`<option value="${esc(id)}" ${id===selected?'selected':''}>${esc(label)}</option>`).join('');
const packed=x=>Array.isArray(x)?{re:x,im:x.map(r=>Array.isArray(r)?r.map(()=>0):0)}:x;
function matrixHTML(value,component='re',title='当前矩阵') {const a=packed(value)?.[component];if(!Array.isArray(a)||!a.length)return '';const rows=Array.isArray(a[0])?a:a.map(x=>[x]);return heatmapSVG(rows[0].map((_,i)=>i),rows.map((_,i)=>i),rows,{title:title+' · '+(component==='re'?'实部':'虚部'),signed:true,xLabel:'列索引（从0开始）',yLabel:'行索引（从0开始）'})+`<details><summary>查看数值矩阵表</summary>${table(rows[0].map((_,i)=>'列 '+i),rows.map(row=>row.map(num)))}</details>`;}
export function pointsSVG(points,yaw=30,showWeights=true){if(!points?.length)return '';points=[...points.reduce((map,p)=>{const key=[p.x,p.y,p.z||0,p.weight||0].map(x=>Number(x).toFixed(10)).join(',');if(map.has(key))map.get(key).label+=' / '+p.label;else map.set(key,{...p});return map;},new Map()).values()];const a=yaw*Math.PI/180,c=Math.cos(a),s=Math.sin(a),xx=points.map(p=>c*p.x-s*p.y),yy=points.map(p=>.35*(s*p.x+c*p.y)-.8*(p.z||0)),xmin=Math.min(...xx),xmax=Math.max(...xx),ymin=Math.min(...yy),ymax=Math.max(...yy),span=Math.max(xmax-xmin,ymax-ymin,1),scale=400/span,weight=Math.max(1e-12,...points.map(p=>Math.abs(p.weight||0)));return `<svg viewBox="0 0 600 350" role="img" aria-label="${showWeights?'模式系数示意，绿色正值、赭色负值；圆大小反映绝对值':'位点或波矢坐标示意，圆点标记位置'}">${points.map((p,i)=>{const x=300+(xx[i]-(xmin+xmax)/2)*scale,y=150+(yy[i]-(ymin+ymax)/2)*Math.min(scale,210/Math.max(ymax-ymin,1)),w=p.weight||0;return `<circle cx="${x}" cy="${y}" r="${showWeights?6+18*Math.sqrt(Math.abs(w)/weight):16}" fill="${w>=0?'#237c66':'#b27232'}" opacity="${Math.abs(w)>1e-12?1:.25}"/><text x="${x}" y="${y+35}" text-anchor="middle">${esc(p.label??i)}${showWeights?': '+num(w):''}</text>`;}).join('')}</svg>`;}
function graphHTML(graph){const nodes=graph.nodes||[],orders=[...new Set(nodes.map(n=>n.order))].sort((a,b)=>b-a),positions=new Map();for(const order of orders){const layer=nodes.filter(n=>n.order===order);layer.forEach((n,i)=>positions.set(n.id,[600*(i+1)/(layer.length+1),45+230*orders.indexOf(order)/Math.max(1,orders.length-1)]));}return `<svg viewBox="0 0 600 330" role="img" aria-label="当前模型的群与子群包含关系，箭头由母群指向子群"><defs><marker id="ct-arrow" markerWidth="9" markerHeight="9" refX="7" refY="3" orient="auto"><path d="M0 0L0 6L8 3Z" fill="#98afa1"/></marker></defs>${(graph.edges||[]).map(e=>{const p=positions.get(e.from),q=positions.get(e.to);if(!p||!q)return '';return `<line x1="${p[0]}" y1="${p[1]+17}" x2="${q[0]}" y2="${q[1]-22}" stroke="#98afa1" stroke-width="2" marker-end="url(#ct-arrow)"/><text x="${(p[0]+q[0])/2+8}" y="${(p[1]+q[1])/2}">${esc(e.label||'')}</text>`;}).join('')}${nodes.map(n=>{const [x,y]=positions.get(n.id);return `<g data-ct-node="${esc(n.id)}" role="button" tabindex="0" aria-label="${esc(n.label)}，阶数${esc(n.order)}"><rect x="${x-72}" y="${y-20}" width="144" height="40" rx="10" fill="${graph.selected===n.id?'#d8ecdf':'#f1f5ef'}" stroke="#477f68"/><text x="${x}" y="${y+7}" text-anchor="middle">${esc(n.label.split(' = ').map(t=>t.split('：')[0]).join(' = '))}</text></g>`;}).join('')}</svg>`;}
export function resultHTML(module,r){const tasks=r.grading?.tasks||[];return `<section class="ct-panel"><h3>表示构造回放</h3><p>每一帧都来自当前 Python 计算。矩阵按列作用于基向量；改变参数后重新运行可得到新的过程。</p><div class="ct-toolbar"><button id="ct-replay-prev" type="button" class="secondary">上一步</button><button id="ct-replay-play" type="button" class="secondary">播放</button><button id="ct-replay-next" type="button" class="secondary">下一步</button></div><label>构造步骤<input id="ct-replay-step" type="range" min="0" max="${Math.max(0,(r.replay?.length||1)-1)}" step="1" value="0"></label><label>矩阵分量<select id="ct-component"><option value="re">实部</option><option value="im">虚部</option></select></label><label>模式观察方向<input id="ct-yaw" type="range" min="0" max="360" value="30"></label><div id="ct-replay-info"></div></section>${r.subgroupGraph?`<section class="ct-panel"><h3>群—子群关系图</h3><p>${esc(r.subgroupGraph.scope||'展示本模型中选取的真实包含关系；不是全部空间群的子群数据库。')} 绿色节点为本次计算的保留群。</p>${graphHTML(r.subgroupGraph)}<label>选择节点<select id="ct-graph-select">${opts(r.subgroupGraph.nodes.map(n=>[n.id,n.label]),r.subgroupGraph.selected)}</select></label><div id="ct-graph-info"></div></section>`:''}${module==='salc'?'<section class="ct-panel"><h3>SALC 与矩阵分块</h3><label>查看矩阵<select id="ct-salc-matrix"><option value="basis">完整 SALC 换基矩阵</option><option value="hamiltonian">原站点基 Hamiltonian</option><option value="blockedHamiltonian">SALC 基 Hamiltonian</option><option value="blockedOperator">SALC 基观测算符</option><option value="energyBasisOperator">能量本征基观测算符</option></select></label><div id="ct-salc-info"></div></section>':''}${module==='wavevector'?`<section class="ct-panel"><h3>超胞图案与对称相关畴</h3><p>坐标 z 与颜色表示无量纲标量场，圆大小反映幅值绝对值；这里的几何高度不自动代表原子的真实位移。</p><label>选择畴<select id="ct-domain">${(r.wavevector?.domains||[]).map((d,i)=>`<option value="${i}">畴 ${i+1} · ${esc(d.representative)}</option>`).join('')}</select></label><div id="ct-domain-info"></div></section>`:''}${r.breaking?`<section class="ct-panel"><h3>最小破缺挑战</h3><p>${esc(r.breaking.goal)}</p><p>先选择扰动，再检查是否达成目标，以及是否还有更少的选择。</p><div>${r.breaking.choices.map(c=>`<label class="ct-choice"><input type="checkbox" aria-label="${esc(c.label)}" data-ct-break="${esc(c.id)}">${esc(c.label)}</label>`).join('')}</div><button id="ct-challenge-check" type="button" class="secondary">验证我的选择</button><p id="ct-challenge-feedback" role="status"></p></section>`:''}${tasks.length?`<section class="ct-panel"><h3>矩阵与子空间作业判分</h3><p>提交二维数值数组，或含 re、im 的复矩阵。每一列为原基底中的一个基向量；比较投影子空间，允许复相位与满秩内部换基。公开示例用于练习，记录会标为参考过示例。</p><label>当前计算生成的题目<select id="ct-grade-task">${opts(tasks.map(t=>[t.id,t.title]),tasks[0].id)}</select></label><label>答案类型<select id="ct-grade-kind"><option value="subspace">子空间基矩阵</option><option value="projector">Hermitian 投影矩阵</option></select></label><p id="ct-grade-instructions"></p><label>矩阵答案<textarea id="ct-grade-answer" rows="8" spellcheck="false" placeholder='例如 [[1,0],[0,1]]；请按题目维数填写'></textarea></label><div class="ct-toolbar"><button id="ct-grade-reference" type="button" class="secondary">填入参考示例</button><button id="ct-grade-equivalent" type="button" class="secondary">填入等价换基示例</button><button id="ct-grade-wrong" type="button" class="secondary">填入错误子空间示例</button><button id="ct-grade-check" type="button" class="primary">检查矩阵答案</button></div><div id="ct-grade-feedback" role="status"></div><p>采用有限维浮点验证，阈值 10⁻⁷；不自动批改自由文本证明。</p></section>`:''}${baseResult('',r)}`;}
export function bindResult(module,r,root,{runGrade,isCurrent=()=>root.isConnected!==false,onEvidence=()=>{}}={}){
 bindBase('',r,root);const $=s=>root.querySelector(s);let timer=null,disposed=false,gradeTicket=0,exampleUsed=false;
 const valid=()=>!disposed&&isCurrent();const stop=()=>{if(timer!==null)clearInterval(timer);timer=null;if($('#ct-replay-play'))$('#ct-replay-play').textContent='播放';};
 const drawReplay=()=>{if(!valid()){stop();return;}const frames=r.replay||[],i=Math.min(frames.length-1,Number($('#ct-replay-step').value)||0),f=frames[i];$('#ct-replay-prev').disabled=i<=0;$('#ct-replay-next').disabled=i>=frames.length-1;$('#ct-replay-info').innerHTML=f?`<h4>${i+1} / ${frames.length} · ${esc(f.title)}</h4><p>${esc(f.text)}</p>${f.points?pointsSVG(f.points,Number($('#ct-yaw').value),module!=='nonsymmorphic'):''}${f.matrix?matrixHTML(f.matrix,$('#ct-component').value):''}${f.vector?matrixHTML(f.vector,$('#ct-component').value,'当前向量'):''}`:'<p>此参数下没有构造步骤。</p>';};
 $('#ct-replay-prev').onclick=()=>{stop();$('#ct-replay-step').value=Math.max(0,Number($('#ct-replay-step').value)-1);drawReplay();};$('#ct-replay-next').onclick=()=>{stop();$('#ct-replay-step').value=Math.min(r.replay.length-1,Number($('#ct-replay-step').value)+1);drawReplay();};$('#ct-replay-step').oninput=()=>{stop();drawReplay();};
 $('#ct-replay-play').onclick=()=>{if(timer!==null){stop();return;}if(Number($('#ct-replay-step').value)>=r.replay.length-1)$('#ct-replay-step').value=0;drawReplay();$('#ct-replay-play').textContent='暂停';timer=setInterval(()=>{if(!valid()){stop();return;}$('#ct-replay-step').value=Number($('#ct-replay-step').value)+1;drawReplay();if(Number($('#ct-replay-step').value)>=r.replay.length-1)stop();},1500);};drawReplay();
 const drawMatrix=()=>{if(module==='salc')$('#ct-salc-info').innerHTML=matrixHTML(r.salc[$('#ct-salc-matrix').value],$('#ct-component').value);};
 const drawDomain=()=>{if(module!=='wavevector')return;const w=r.wavevector,d=w.domains[Number($('#ct-domain').value)||0];if(!d)return;const points=w.points.map((p,i)=>({...p,z:d.field[i],weight:d.field[i]}));$('#ct-domain-info').innerHTML=pointsSVG(points,Number($('#ct-yaw').value))+`<details><summary>查看所有位点的场值</summary>${table(['位点','当前场值'],points.map(p=>[p.label,num(p.weight)]))}</details>`;};
 $('#ct-component').onchange=()=>{drawReplay();drawMatrix();};$('#ct-yaw').oninput=()=>{drawReplay();drawDomain();};if(module==='salc'){$('#ct-salc-matrix').onchange=drawMatrix;drawMatrix();}if(module==='wavevector'){$('#ct-domain').onchange=drawDomain;drawDomain();}
 if(r.subgroupGraph){const draw=()=>{const node=r.subgroupGraph.nodes.find(n=>n.id===$('#ct-graph-select').value);$('#ct-graph-info').innerHTML=node?`<h4>${esc(node.label)} · 阶 ${esc(node.order)}</h4><p>${esc(val(node.details))}</p>`:'';};$('#ct-graph-select').onchange=draw;root.querySelectorAll('[data-ct-node]').forEach(el=>{const choose=()=>{$('#ct-graph-select').value=el.dataset.ctNode;draw();};el.onclick=choose;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};});draw();}
 if(r.breaking){root.querySelectorAll('[data-ct-break]').forEach(el=>el.onchange=()=>{$('#ct-challenge-feedback').textContent='选择已改变，请重新验证。';onEvidence('breaking',null);});$('#ct-challenge-check').onclick=()=>{const chosen=[...root.querySelectorAll('[data-ct-break]')].filter(el=>el.checked).map(el=>el.dataset.ctBreak).sort(),candidate=r.breaking.candidates.find(c=>JSON.stringify([...c.removed].sort())===JSON.stringify(chosen));if(!candidate){$('#ct-challenge-feedback').textContent='当前组合没有可用的计算证据。';return;}const minimal=candidate.achieved&&chosen.length===r.breaking.minimalCount,report={selected:chosen,achieved:candidate.achieved,minimal,reason:candidate.reason,verifiedAt:new Date().toISOString()};$('#ct-challenge-feedback').textContent=(minimal?'✓ 目标达成，且选择数最少。':candidate.achieved?'目标达成，但还有更少的选择。':'尚未达成目标。')+' '+candidate.reason;onEvidence('breaking',report);};}
 if(r.grading?.tasks?.length){const task=()=>r.grading.tasks.find(t=>t.id===$('#ct-grade-task').value)||r.grading.tasks[0],clearGrade=(reset=false)=>{gradeTicket++;$('#ct-grade-feedback').textContent='答案已改变，请重新检查。';$('#ct-grade-check').disabled=false;if(reset){$('#ct-grade-answer').value='';exampleUsed=false;}onEvidence('matrix',null);const t=task(),n=t.reference.re.length,d=t.reference.re[0].length;$('#ct-grade-instructions').textContent=t.instructions+' 当前需要 '+n+' 行、'+($('#ct-grade-kind').value==='projector'?n:d)+' 列。';};
  $('#ct-grade-task').onchange=()=>clearGrade(true);$('#ct-grade-kind').onchange=()=>clearGrade(true);$('#ct-grade-answer').oninput=()=>clearGrade();clearGrade(true);
  const execute=async(example)=>{if(!runGrade){$('#ct-grade-feedback').textContent='当前环境没有 Python 判分器。';return;}let answer;if(!example){try{const text=$('#ct-grade-answer').value;if(text.length>250000)throw Error('矩阵文本过长');answer=JSON.parse(text);}catch(e){$('#ct-grade-feedback').textContent='请填写合法的数值 JSON 矩阵：'+e.message;return;}}const id=++gradeTicket,t=task(),kind=$('#ct-grade-kind').value;$('#ct-grade-check').disabled=true;$('#ct-grade-feedback').textContent='正在用 Python 验证矩阵…';try{const output=await runGrade({task:t,kind,...(example?{mode:'example',example}:{answer,mode:'grade'})});if(!valid()||id!==gradeTicket)return;if(example){exampleUsed=true;$('#ct-grade-answer').value=JSON.stringify(output.candidate,null,2);$('#ct-grade-feedback').textContent=output.note;onEvidence('matrix',null);}else{$('#ct-grade-feedback').innerHTML=`<p>${esc(output.feedback)}</p>${table(['检查项','结果','残差或秩'],output.checks.map(c=>[c.label,c.passed?'通过':'未通过',num(c.value)]))}<p>${esc(output.scope)}</p>`;onEvidence('matrix',{...output,answer,referenceExampleUsed:exampleUsed,verifiedAt:new Date().toISOString()});}}catch(e){if(valid()&&id===gradeTicket)$('#ct-grade-feedback').textContent=e.message;}finally{if(valid()&&id===gradeTicket)$('#ct-grade-check').disabled=false;}};
  $('#ct-grade-check').onclick=()=>execute();for(const key of ['reference','equivalent','wrong'])$('#ct-grade-'+key).onclick=()=>execute(key);
 }
 return ()=>{disposed=true;gradeTicket++;stop();};
}
